Method.Implementation:
 #dim tSC As %Status = $$$OK
 #dim clsList As  %ListOfDataTypes

 set details = ""
 set ..DeployDirectory = $$$USRRELEASEBASEDIR _ usrNm _ $$$SVNSRCTRUNK

 NEW $NAMESPACE
 try {
 	set $NAMESPACE = nmSp
  } catch err
 {
	 return $$$ERROR($$$GeneralError, "Invalid Namespace: " _ nmSp _ err.Name _ " " _ err.Code)
 }

 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "VerifyClassFiles: " _ tItemName _ " in NAMESPACE: " _ $NAMESPACE) 
 set tProductionName = ##class(Ens.Director).GetActiveProductionName()

 if tProductionName = ""
 {
  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Could not get active production in " _ $NAMESPACE)
  Quit $$$ERROR($$$GeneralError, "Active production not found")
 }
 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Active PROD: " _ tProductionName)

 if env = ""
 {
	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Specify the environment")
  	  Quit $$$ERROR($$$GeneralError, "The environment is required to pull the file information from the Database")
 }
  set $NAMESPACE = "DEPLOYHIST"

  Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).DoSvnSetup(usrNm, passwd)
  try
  {
  set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
  set depCl.Username = usrNm
  set depCl.Password = passwd
  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Call GetLastImplementationDetails")
  Set depCl.Location = ..WSLocation
  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "URL Location: " _ depCl.Location _ "; Set location: " _ ..WSLocation)
  set compImpl = depCl.GetLastImplementationDetails(tItemName, env, nmSp)
  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "GetLastImplementationDetails: " _ compImpl)
  Set tExportClsFilename = $P(compImpl, ";", 1)
  Set rev = $P(compImpl, ";", 2)
  set details = tItemName _ ";ImplementationFile: " _ tExportClsFilename _ "; subversion # " _ rev _ "; Implemention Date: " _  $P(compImpl, ";", 3)
  } catch err
  {
	  If $ZERROR["<ZSOAP>" {
                	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  %objlasterror)
                	Set tSC=$$$ERROR($$$GeneralError, "Error in getting ImplementationDetails from Web service: "  _ depCl.SoapFault.detail)
                	set details = depCl.SoapFault.detail
		 		} Else {
            		Set tSC=$$$ERROR($$$GeneralError, "Error in getting ImplementationDetails from web service:" _ $ZERROR)
		 		}

	  return tSC
  }
  if (tExportClsFilename  [ "_CLS_")
   {
  	try
  	{

  		set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
   		set depCl.Username = usrNm
  		set depCl.Password = passwd
    	Set depCl.Location = ..WSLocation

  		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Call GetClassesForComponent")
  		set clsList = depCl.GetClassesForComponent(tItemName, nmSp, rev)
  		set details = details _ "; Number of classes in list: " _ clsList.Count()
  		Do clsList.Insert(tItemName)
   		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Number of classes in list: " _ clsList.Count())

    } catch err
  	{
	  If $ZERROR["<ZSOAP>" {
                	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  %objlasterror)
                	Set tSC=$$$ERROR($$$GeneralError, "Error in getting GetClassesForComponent from Web service: "  _ depCl.SoapFault.detail)
                	set details = depCl.SoapFault.detail
		 		} Else {
            		Set tSC=$$$ERROR($$$GeneralError, "Error in getting GetClassesForComponent from web service:" _ $ZERROR)
		 		}

	  return tSC
    }
  	set $NAMESPACE = nmSp

  	// Get corresponding full path for current user
  	set ind = $FIND(tExportClsFilename, $$$SVNSRCTRUNK)
    set tExportClsFilename = ..DeployDirectory _ $E(tExportClsFilename, ind, *)

  	set tSC = ..CheckoutFile(tExportClsFilename, usrNm, passwd, rev )
  	set tSC = ..CheckClassFiles(tItemName, clsList, tExportClsFilename, nmSp, usrNm, passwd, env, .details ) 
  }
 Quit tSC

  #dim tSC As %Status

  set tSC = $$$OK
  NEW $NAMESPACE
  set $NAMESPACE = "DEPLOYHIST"



 set parseFl = ##class(IHC.ITF.SrcCtrlPkg.parseXmlFile).%New()
 set tSC = parseFl.ParseFile(tExportClsFilename, tItemName)

 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) )
  {
	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "parseFl.itemsInfo cnt: " _ parseFl.itemsInfo.Count())
	 if (parseFl.itemsInfo.Count() < 2)
	 {
		  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "File does not have config for any class in file" _ compNm)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for any class in file " _ compNm)
	 }
	 if (parseFl.itemsInfo.Count() '= clsList.Count())
	 {
		 set tSC =  $$$ERROR($$$GeneralError, "Number of classes in DB and classfile do not match")
		 Quit
	 }
	 if ($ZCVT(parseFl.itemsInfo.GetAt(1).itemName, "U") = $ZCVT(tItemName, "U") )
	 {
 		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Check: " _ tItemName)
	 	FOR ind=2:1:parseFl.itemsInfo.Count()
	 	{
		 	set clsNm = parseFl.itemsInfo.GetAt(ind).itemName
		 	if clsList.Find($ZCVT(clsNm, "U"))
		 	{
			 	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Call CompareClassInternalWithSrcCtrl " _ tItemName _ ", Class: " _ clsNm)
			 	if ( $F(clsNm, "HL7") > $L(clsNm))
	 			{
		 			set details = details _ "; " + clsNm_": HL7 schema is not compared: " _ clsNm
	 				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( usrNm _ ", Excluded file: " _ clsNm)
	 			}
	 			else
	 			{	
	   				set tSC = ..CompareClassInternalWithSrcCtrl(clsNm,nmSp,
	   	 				usrNm, passwd, env, parseFl.itemsInfo.GetAt(ind).versionNum, .details)
	 				if $$$ISERR(tSC)
	 				{
		 				Quit
	 				}
	 			}
		 	}
		 	else
		 	{
			 	set tSC =  $$$ERROR($$$GeneralError, "Could not find class name being deployed " _ clsNm)
			 	Quit
		 	}
	 	}
	 }
	 else
	 {
		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "File does not have config for " _ tItemName _ ", First item: " _ parseFl.itemsInfo.GetAt(1).itemName)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for " _ tItemName)
	 }
  }
  else
  {
	   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "ParseFile of" _ tExportClsFilename _ " failed")
  }
  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "VerifyClassFiles exit: " _ tSC)
  Quit tSC

  set tSC = $$$OK

  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "In CompareClassInternalWithSrcCtrl " _ clsName)
  NEW $NAMESPACE
  set $NAMESPACE = "DEPLOYHIST"
  set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
  set depCl.Username = usrNm
  set depCl.Password = passwd
  Set depCl.Location = ..WSLocation

  set clsList = depCl.GetClassInformation(clsName, env, revNum)
  for ind=1:1:clsList.Count()
  {
	  set retVal = clsList.GetAt(ind)
	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "clsList.GetAt " _ ind _ ": " _ retVal)
	  set clsNm = $Piece(retVal, ",", 1)
	  set clsfile = $Piece(retVal, ",", 2) 
	  set version = $Piece(retVal, ",", 3) 
	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   clsNm _ ", " _ clsfile _ ", " _ version)
	  set extNm = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExternalName(clsName, usrNm)
	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  "External name: " _ extNm)

	  set cmd = "LD_LIBRARY_PATH=/lib64:"_$SYSTEM.Util.BinaryDirectory()_";svn update  -N --no-auth-cache --non-interactive --revision " _ version _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _extNm
	  set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
	  set details = details _ "; class: " _ extNm _ "; subversion #: " _ version
	  // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "cmd: " _cmd _ ": " _ stat)
	  if (stat = 0)
	  {
		     // Export internal code
		     set tempFile = ##class(%Library.File).TempFilename()


			 if ($$$ISERR( ..exportFile(tempFile, clsName, nmSp)))
			 {
				 set tSC = $$$ERROR($$$GeneralError, "Could not export file for " _ clsName)
				 set details = details _ "; Could not export file for " _ clsName
				 Quit
			 }
			 if (  ##class(%File).Exists(tempFile))
			 {
			     	set tempFile2 = ##class(%Library.File).TempFilename()
			     	set cmd = "diff -w -B --suppress-common-lines " _ extNm _ " " _ tempFile _ " > " _ tempFile2
			   		Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
			      	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   cmd _ " Stat: " _ stat)
			   	    if ((stat = 0) && (##class(%File).Exists(tempFile2)))
			   	    {
				   	    if ##class(%File).GetFileSize(tempFile2) > 0
			   			{
				   			set tSC = $$$ERROR($$$GeneralError, "Src Control File is not current for " _ clsName)
				   			set details = details _ "; Src Control File is not current for " _ clsName _ "; DIFF: " _ ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).GetFileContent(tempFile2)
				   			Quit
			   			}
         				Do ##class(%Library.File).Delete(tempFile2)
         				Do ##class(%Library.File).Delete(tempFile)
			   	    }
			   	    else
			   	    {
				   	    set tSC = $$$ERROR($$$GeneralError, "diff failed for " _ clsName)
				   	    Quit 
			   	    }
			 }
			 else
			 {
			     	set tSC = $$$ERROR($$$GeneralError, " Export failed: " _ clsName )
			     	Quit
			 }
		}
		else
		{
		   set tSC = $$$ERROR($$$GeneralError, "Unable to run svn update command for: " _ extNm)
		   Quit
		}
    }

	if $$$ISOK(tSC)
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   " SVN file content matches internal code " _ clsName)
		set details = details _ "; SVN file content matches internal code " _ clsName
	}


  QUIT tSC

	set tSC = $$$OK
	if (rev '= "")
	{
		Do ##class(%File).Delete(fileNm)
		Set cmd= $$$SVNUPDATE _ " --revision " _ rev
		Set cmd= cmd _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _  fileNm 

		Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

		if (status '= 0)
		{
			set tSC = $$$ERROR($$$GeneralError, $$$SVNUPDATE _ " --revision " _ rev _ " failed")
		}
		if ##class(%File).Exists(fileNm)
		{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Checked out " _ fileNm _ ", version: " _ rev)
		}
		else {
  			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Could not find file " _ fileNm)
  			set tSC = $$$ERROR($$$GeneralError, "Could not find file " _ fileNm)
 		}
	}
	else
	{		
		  set tSC = $$$ERROR($$$GeneralError, "Checkout: Revision number is required") 
	}

 	Quit tSC
